      "path": "lib/upload.js",
      "content": "/**\n * dsh-boo550wt-animation — custom upload storage.\n *\n * Users can upload their own video / image / html for the boot animation from\n * the Settings panel. Uploads land in a dedicated directory next to the\n * settings file, with a `.meta.json` ledger (title + sha256) so identical\n * re-uploads return the existing entry instead of piling up copies.\n *\n * Disciplines (borrowed from dsh-plugin-wallpaper-engine):\n *   - Stream to a `.tmp` file while hashing; rename is the atomic publish.\n *   - Backpressure: pause the request when the write buffer fills.\n *   - On client abort / error / timeout, destroy the stream and clean the\n *     `.tmp` — never leave an open handle or a partial file behind.\n *   - The meta ledger is written atomically and read through a non-throwing\n *     reader; a broken or missing ledger degrades to {}.\n */\n\nimport { createHash } from \"node:crypto\";\nimport {\n  createWriteStream,\n  existsSync,\n  mkdirSync,\n  readFileSync,\n  readdirSync,\n  renameSync,\n  unlinkSync,\n  writeFileSync,\n} from \"node:fs\";\nimport { extname, join } from \"node:path\";\n\nexport const UPLOAD_MAX_BYTES = 512 * 1024 * 1024;\nconst CONTROL_MAX_BYTES = 1024 * 1024;\nconst BODY_IDLE_MS = 60_000;\n\n/** MIME type -> extension for the kinds the boot animation accepts. */\nconst UPLOAD_EXT = {\n  \"image/png\": \"png\",\n  \"image/jpeg\": \"jpg\",\n  \"image/jpg\": \"jpg\",\n  \"image/gif\": \"gif\",\n  \"image/webp\": \"webp\",\n  \"video/mp4\": \"mp4\",\n  \"video/webm\": \"webm\",\n  \"text/html\": \"html\",\n  \"application/xhtml+xml\": \"html\",\n};\n\n/** Map a stored extension to the boot mode it can drive. */\nexport function uploadKind(ext) {\n  if (ext === \"mp4\" || ext === \"webm\") return \"video\";\n  if (ext === \"html\") return \"web\";\n  return \"image\";\n}\n\n/** Directory holding uploaded assets; created on demand. */\nexport function uploadDir() {\n  const base = process.env.DSH_HOME?.trim() || process.cwd();\n  const dir = join(base, \"boot-animation-uploads\");\n  mkdirSync(dir, { recursive: true });\n  return dir;\n}\n\nfunction metaPath() {\n  return join(uploadDir(), \".meta.json\");\n}\n\n/** Read the ledger; missing / broken / non-object degrades to {}. */\nexport function readMeta() {\n  const p = metaPath();\n  if (!existsSync(p)) return {};\n  try {\n    const o = JSON.parse(readFileSync(p, \"utf8\"));\n    return o && typeof o === \"object\" && !Array.isArray(o) ? o : {};\n  } catch {\n    return {};\n  }\n}\n\n/** Publish the ledger atomically. */\nfunction writeMeta(meta) {\n  const p = metaPath();\n  const tmp = `${p}.tmp${process.pid}`;\n  writeFileSync(tmp, JSON.stringify(meta, null, 2), \"utf8\");\n  renameSync(tmp, p);\n}\n\n/**\n * Resolve one stored file name to its absolute path.\n * The id is a bare file name generated by this module; the prefix and the\n * containment check keep path traversal impossible.\n */\nexport function resolveUpload(name) {\n  if (typeof name !== \"string\" || !/^up-[A-Za-z0-9.-]+$/.test(name)) return null;\n  const dir = uploadDir();\n  const full = join(dir, name);\n  if (!full.startsWith(dir) || !existsSync(full)) return null;\n  return full;\n}\n\n/** List every stored asset with its ledger entry. */\nexport function listUploads() {\n  const dir = uploadDir();\n  const meta = readMeta();\n  const out = [];\n  let names = [];\n  try {\n    names = readdirSync(dir);\n  } catch {\n    return out;\n  }\n  for (const name of names) {\n    if (!name.startsWith(\"up-\") || name.endsWith(\".tmp\")) continue;\n    const entry = meta[name] && typeof meta[name] === \"object\" ? meta[name] : {};\n    const ext = extname(name).slice(1).toLowerCase();\n    out.push({\n      name,\n      title: typeof entry.title === \"string\" && entry.title.trim() ? entry.title : name,\n      sha256: typeof entry.sha256 === \"string\" ? entry.sha256 : null,\n      bytes: typeof entry.bytes === \"number\" ? entry.bytes : null,\n      kind: uploadKind(ext),\n      url: `/boot-animation/uploads/${encodeURIComponent(name)}`,\n    });\n  }\n  out.sort((a, b) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0));\n  return out;\n}\n\nfunction json(res, status, body) {\n  const payload = JSON.stringify(body);\n  res.statusCode = status;\n  res.setHeader(\"Content-Type\", \"application/json; charset=utf-8\");\n  res.setHeader(\"Cache-Control\", \"no-store\");\n  res.end(payload);\n}\n\n/**\n * Handle POST /upload: stream the raw body to a `.tmp` file, hash it,\n * deduplicate by sha256, then publish with a ledger entry.\n */\nexport function handleUpload(req, res) {\n  const method = (req.method || \"GET\").toUpperCase();\n  if (method !== \"POST\") {\n    res.statusCode = 405;\n    res.end(\"method not allowed\");\n    return;\n  }\n  const query = new URL(req.url || \"/\", \"http://x\").searchParams;\n  const title = (query.get(\"title\") || \"\").trim().slice(0, 80);\n  const ctype = String(req.headers[\"content-type\"] || \"\").split(\";\")[0].trim().toLowerCase();\n  const ext = UPLOAD_EXT[ctype];\n  if (!ext) {\n    json(res, 415, {\n      error: `不支持的格式：${ctype || \"(空)\"}（仅支持 PNG / JPG / GIF / WEBP / MP4 / WEBM / HTML）`,\n    });\n    return;\n  }\n\n  const dir = uploadDir();\n  const name = `up-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}.${ext}`;\n  const fileAbs = join(dir, name);\n  const tmpAbs = `${fileAbs}.tmp`;\n  const hash = createHash(\"sha256\");\n  const ws = createWriteStream(tmpAbs);\n  let size = 0;\n  let failed = false;\n  let completed = false;\n  let idle = null;\n\n  const cleanupTmp = () => {\n    try { unlinkSync(tmpAbs); } catch { /* ignore */ }\n  };\n  const fail = (code, payload) => {\n    if (failed) return;\n    failed = true;\n    if (idle !== null) clearTimeout(idle);\n    try { ws.destroy(); } catch { /* ignore */ }\n    json(res, code, payload);\n  };\n\n  ws.on(\"error\", () => fail(500, { error: \"upload write failed\" }));\n  ws.on(\"close\", () => { if (failed) cleanupTmp(); });\n  // A client that disappears mid-upload never reaches 'end': clean up here.\n  req.once(\"close\", () => {\n    if (completed || failed) return;\n    failed = true;\n    if (idle !== null) clearTimeout(idle);\n    try { ws.destroy(); } catch { /* ignore */ }\n    cleanupTmp();\n  });\n\n  const armIdle = () => {\n    if (idle !== null) clearTimeout(idle);\n    idle = setTimeout(() => fail(408, { error: \"request timeout\" }), BODY_IDLE_MS);\n  };\n  armIdle();\n\n  req.on(\"data\", (chunk) => {\n    if (failed) return;\n    armIdle();\n    size += chunk.length;\n    if (size > UPLOAD_MAX_BYTES) {\n      fail(413, { error: \"文件过大（上限 512MB）\" });\n      return;\n    }\n    hash.update(chunk);\n    // Backpressure: a full write buffer pauses the request until 'drain'.\n    if (!ws.write(chunk)) req.pause();\n  });\n  ws.on(\"drain\", () => { if (!failed) req.resume(); });\n\n  req.on(\"end\", () => {\n    if (idle !== null) clearTimeout(idle);\n    if (failed) return;\n    completed = true;\n    ws.end(() => {\n      try {\n        const sha = hash.digest(\"hex\");\n        const meta = readMeta();\n        // Content dedup: the same bytes must not become a second entry.\n        for (const known of Object.keys(meta)) {\n          const entry = meta[known] && typeof meta[known] === \"object\" ? meta[known] : {};\n          if (entry.sha256 !== sha) continue;\n          const existing = resolveUpload(known);\n          if (existing === null) continue;\n          failed = true; // so ws 'close' removes the fresh .tmp\n          json(res, 200, {\n            name: known,\n            title: typeof entry.title === \"string\" && entry.title.trim() ? entry.title : known,\n            kind: uploadKind(extname(existing).slice(1).toLowerCase()),\n            duplicate: true,\n            url: `/boot-animation/uploads/${encodeURIComponent(known)}`,\n          });\n          return;\n        }\n        renameSync(tmpAbs, fileAbs);\n        meta[name] = { title: title || name, sha256: sha, bytes: size };\n        writeMeta(meta);\n        json(res, 200, {\n          name,\n          title: title || name,\n          kind: uploadKind(ext),\n          bytes: size,\n          url: `/boot-animation/uploads/${encodeURIComponent(name)}`,\n        });\n      } catch (err) {\n        failed = true;\n        json(res, 500, { error: String(err && err.message ? err.message : err) });\n      }\n    });\n  });\n  req.on(\"error\", () => fail(400, { error: \"request error\" }));\n}\n\n/** Handle POST /upload-remove: delete one stored asset by name. */\nexport function handleRemove(req, res) {\n  const method = (req.method || \"GET\").toUpperCase();\n  if (method !== \"POST\") {\n    res.statusCode = 405;\n    res.end(\"method not allowed\");\n    return;\n  }\n  const chunks = [];\n  let size = 0;\n  let tooLarge = false;\n  req.on(\"data\", (chunk) => {\n    size += chunk.length;\n    if (size > CONTROL_MAX_BYTES) {\n      tooLarge = true;\n      req.destroy();\n      return;\n    }\n    chunks.push(chunk);\n  });\n  req.on(\"end\", () => {\n    if (tooLarge) return;\n    let body;\n    try {\n      body = JSON.parse(Buffer.concat(chunks).toString(\"utf8\") || \"{}\");\n    } catch {\n      json(res, 400, { error: \"invalid JSON\" });\n      return;\n    }\n    const name = body?.name;\n    if (typeof name !== \"string\") {\n      json(res, 400, { error: \"missing name\" });\n      return;\n    }\n    const file = resolveUpload(name);\n    if (file === null) {\n      json(res, 404, { error: \"not found\" });\n      return;\n    }\n    try {\n      unlinkSync(file);\n      const meta = readMeta();\n      delete meta[name];\n      writeMeta(meta);\n      json(res, 200, { ok: true, name });\n    } catch (err) {\n      json(res, 500, { error: String(err && err.message ? err.message : err) });\n    }\n  });\n  req.on(\"error\", () => json(res, 400, { error: \"request error\" }));\n}\n"
    }
  ],
